function validate([grid]) {
  const n = Array.isArray(grid) ? grid.length : 0;
  if (n < 2 || n > 100) return 'grid needs 2 to 100 rows.';
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'grid must be square.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every cell is 0 or 1.';
  for (let i = 0; i < n; i++) {
    if (grid[i][i] !== 0) return 'The diagonal must be all 0.';
    for (let j = i + 1; j < n; j++) if (grid[i][j] === grid[j][i]) return 'For i != j, grid[i][j] and grid[j][i] must differ.';
  }
  // A complete tournament is transitive exactly when the win counts are 0, 1, ..., n - 1.
  const wins = new Set(grid.map(row => row.reduce((s, v) => s + v, 0)));
  if (wins.size !== n) return 'Strength must be transitive.';
  return null;
}

