function findChampion(grid) {
  const n = grid.length;
  for (let team = 0; team < n; team++) {
    let wins = 0;
    for (let other = 0; other < n; other++) {
      wins += grid[team][other];
    }
    if (wins === n - 1) {
      return team;
    }
  }
  return -1;
}

