function findChampion(grid) {
  const n = grid.length;
  const beaten = new Array(n).fill(false);
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      if (i !== j && grid[i][j] === 0) beaten[i] = true;
  return beaten.indexOf(false);
}

